export function step(state, dt) {
  const { ball, paddle } = state;
  const prevX = ball.x;
  const prevY = ball.y;

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle: swept test — the ball bounces when its bottom edge crosses the
  // paddle's top plane during this step, whatever the frame rate (see D6).
  const bottom0 = prevY + ball.r;
  const bottom1 = ball.y + ball.r;
  if (
    ball.vy > 0 &&
    bottom1 >= paddle.y &&
    bottom0 <= paddle.y + paddle.h
