// Minimum paddle hit (fraction of the paddle half-width) kept after a bounce:
// a dead-center hit (hit = 0) must still give the ball a horizontal drift, or
// the ball loops vertically forever (defect D8, dead angle).
export const MIN_PADDLE_HIT = 0.1;

const STORAGE_KEY = 'neon.best';

// --- Brick collision (swept resolution, tested) ----------------------------

// How far past the contact point the ball is nudged, so it never starts the
// next step still touching the brick it bounced off.
const RESOLVE_EPS = 1e-3;

// Resolves the ball against the bricks for the current step.
//
// The ball is swept along the segment from `prev` (its position at the start
// of the step) to its current position: for each live brick we expand the box
// by the ball radius and find the earliest contact of the segment with it
// (slab method). The earliest contact wins — a fast ball breaks the FIRST
// brick it crosses instead of tunnelling through it (defect D2) — and every
// brick whose expanded box contains the contact point is broken in the same
// pass, so a seam straddle (gap 8 < ball diameter 14) breaks both bricks with
// exactly ONE velocity flip per axis (defect D4).
//
// A ball already overlapping a brick at the start of the step is resolved
// discretely: the axis of least penetration is the face hit (both axes on an
// exact corner, defect D5), the ball is pushed back out of the rectangle
// (defect D3) and that axis' velocity flips (defect D1).
//
// Returns the number of bricks broken (0 if none).
export function resolveBricks(state, prev) {
  const { ball, bricks } = state;
  const r = ball.r;
  const dx = ball.x - prev.x;
  const dy = ball.y - prev.y;

  let contact = null; // earliest swept contact
  let stuck = null; // brick overlapped at the start of the step

  for (const brick of bricks) {
    if (!brick.alive) continue;
    const xmin = brick.x - r;
    const xmax = brick.x + brick.w + r;
    const ymin = brick.y - r;
    const ymax = brick.y + brick.h + r;

    if (prev.x > xmin && prev.x < xmax && prev.y > ymin && prev.y < ymax) {
      // Already overlapping at the start of the step: discrete separation.
      const penX = Math.min(prev.x + r - brick.x, brick.x + brick.w - (prev.x - r));
      const penY = Math.min(prev.y + r - brick.y, brick.y + brick.h - (prev.y - r));
      if (!stuck || penX + penY < stuck.penX + stuck.penY) {
        stuck = { brick, penX, penY, x: prev.x, y: prev.y };
      }
      continue;
    }

    // Swept contact: slab method over the expanded box.
    let entryX = 0;
    let exitX = Infinity;
    if (dx === 0) {
      if (prev.x <= xmin || prev.x >= xmax) continue;
    } else {
      entryX = Math.min((xmin - prev.x) / dx, (xmax - prev.x) / dx);
      exitX = Math.max((xmin - prev.x) / dx, (xmax - prev.x) / dx);
    }
    let entryY = 0;
    let exitY = Infinity;
    if (dy === 0) {
      if (prev.y <= ymin || prev.y >= ymax) continue;
    } else {
      entryY = Math.min((ymin - prev.y) / dy, (ymax - prev.y) / dy);
      exitY = Math.max((ymin - prev.y) / dy, (ymax - prev.y) / dy);
    }
    const tEnter = Math.max(entryX, entryY, 0);
    const tExit = Math.min(exitX, exitY);
    if (tEnter >= tExit || tEnter > 1) continue;
    if (!contact || tEnter < contact.t) {
      // The face is the slab whose entry binds last (the earliest contact).
      let nx = 0;
      let ny = 0;
      if (entryX > entryY) nx = dx > 0 ? LEFT : RIGHT;
      else if (entryY > entryX) ny = dy > 0 ? UP : DOWN;
      else {
        // Entered both slabs at the same time: an exact corner.
        nx = dx > 0 ? LEFT : RIGHT;
        ny = dy > 0 ? UP : DOWN;
      }
      contact = {
        brick,
        t: tEnter,
        nx,
        ny,
        x: prev.x + dx * tEnter,
        y: prev.y + dy * tEnter,
      };
    }
  }

  // The overlap at the start (t = 0) happens before any swept contact: resolve
  // it first, breaking every brick the ball touches at that point.
  const hit = stuck ?? contact;
  if (!hit) return 0;

  const px = hit.x;
  const py = hit.y;
  let broken = 0;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    // Expanded-box containment: the ball touches the brick at the contact.
    if (px >= brick.x - r && px <= brick.x + brick.w + r && py >= brick.y - r && py <= brick.y + brick.h + r) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      broken += 1;
    }
  }
  if (broken === 0) return 0;

  // Bounce: flip the face axis (or both, on a corner), then push the ball out
  // of the rectangle — past the face for a swept contact, back to the nearest
  // face for an overlap.
  let nx = hit.nx;
  let ny = hit.ny;
  let bx = px;
  let by = py;
  if (stuck) {
    const { brick, penX, penY } = stuck;
    const leftPen = px + r - brick.x;
    const rightPen = brick.x + brick.w - (px - r);
    const topPen = py + r - brick.y;
    const bottomPen = brick.y + brick.h - (py - r);
    if (penX < penY) nx = leftPen <= rightPen ? LEFT : RIGHT;
    else if (penY < penX) ny = topPen <= bottomPen ? UP : DOWN;
    else {
      // Exact corner: both axes flip.
      nx = leftPen <= rightPen ? LEFT : RIGHT;
      ny = ball.vy > 0 ? UP : DOWN;
    }
    if (nx !== 0) bx = nx === LEFT ? brick.x - r : brick.x + brick.w + r;
    if (ny !== 0) by = ny === UP ? brick.y - r : brick.y + brick.h + r;
  } else {
    bx += nx * RESOLVE_EPS;
    by += ny * RESOLVE_EPS;
  }
  if (nx !== 0) ball.vx = Math.abs(ball.vx) * nx;
  if (ny !== 0) ball.vy = Math.abs(ball.vy) * ny;
  ball.x = bx;
  ball.y = by;
  return broken;
}

