// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle and the bricks. `prev` is the ball's position at the
// start of the step, captured before moving: the paddle and the bricks are
// resolved by sweeping the ball along that segment, so a fast ball bounces
// instead of tunnelling through (defects D2, D6).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const prev = { x: ball.x, y: ball.y };

  ball.x += ball.vx * dt;
  ball.y += ball.vy * dt;

  // Side walls
  if (ball.x - ball.r < 0) {
    ball.x = ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (ball.x + ball.r > WIDTH) {
    ball.x = WIDTH - ball.r;
    ball.vx = -Math.abs(ball.vx);
  }

  // Ceiling
  if (ball.y - ball.r < 0) {
    ball.y = ball.r;
    ball.vy = Math.abs(ball.vy);
  }

  // Paddle — swept over the paddle top: the ball bounces when its bottom edge
  // crosses the paddle plane during this step, whatever the frame rate (a
  // discrete point-in-band test lets a 13 px step — level 1 — jump the 12 px
  // band and pass straight through, defect D6).
  const bottom0 = prev.y + ball.r;
  const bottom1 = ball.y + ball.r;
  const crossed = ball.vy > 0 && bottom0 <= paddle.y + paddle.h && bottom1 >= paddle.y;
  if (crossed) {
    // Where the bottom edge crosses the paddle top, horizontally.
    const t = (paddle.y - bottom0) / (bottom1 - bottom0);
    const crossX = prev.x + (ball.x - prev.x) * t;
    if (crossX >= paddle.x && crossX <= paddle.x + paddle.w) {
      ball.y = paddle.y - ball.r;
      // The rebound angle depends on where the paddle was hit, mapped to
      // [-1, 1]; a minimum hit keeps the ball from looping vertically on a
      // dead-center bounce (defect D8).
      const hit = (crossX - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      let h = Math.max(-1, Math.min(1, hit));
      if (Math.abs(h) < MIN_PADDLE_HIT) h = (h < 0 ? -1 : 1) * MIN_PADDLE_HIT;
      // The paddle controls the angle, but the speed of the bounce stays the
      // level speed: the vertical component is renormalized so that
      // sqrt(vx^2 + vy^2) == ballSpeed(level) (defect D7).
      const speed = ballSpeed(state.level);
      const vx = speed * 0.6 * h;
      ball.vx = vx;
      ball.vy = -Math.sqrt(Math.max(0, speed * speed - vx * vx));
      state.combo = 0; // touching the paddle resets the combo
    }
  }

  // Bricks: swept resolution (bounce + break + score).
  resolveBricks(state, prev);

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

